<script setup>
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { computed, reactive } from 'vue';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import Pagination from '../../../Components/Pagination.vue';
import Icon from '../../../Components/Icon.vue';

const props = defineProps({ products: Object, categories: Array, filters: Object, counts: Object });
const page = usePage();
const trash = computed(() => props.filters.view === 'trash');
const form = reactive({ search: props.filters.search || '', status: props.filters.status || '', sync: props.filters.sync || '', category: props.filters.category || '', view: props.filters.view || '' });
const apply = () => router.get('/admin/products', form, { preserveState: true, replace: true });
const switchView = (view) => router.get('/admin/products', { view: view || undefined });
const destroy = (product) => confirm(`Delete “${product.name}”? It will be moved to Trash and can be restored later.`) && router.delete(`/admin/products/${product.slug}`);
const restore = (product) => router.post(`/admin/products/${product.id}/restore`, {}, { preserveScroll: true });
const sync = (product) => router.post(`/admin/merchant/products/${product.slug}`, {}, { preserveScroll: true });
const money = (value) => new Intl.NumberFormat('en-TZ', { style: 'currency', currency: page.props.store.currency, maximumFractionDigits: 0 }).format(value || 0);
const syncBadge = (status) => status === 'synced' ? 'bg-emerald-100 text-emerald-700' : status === 'failed' ? 'bg-red-100 text-red-700' : status === 'pending' ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-600';
const statusBadge = (status) => status === 'active' ? 'bg-emerald-100 text-emerald-700' : status === 'draft' ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-600';
</script>

<template>
    <AdminLayout>
        <Head title="Products" />
        <div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="section-kicker">Product management</p><h1 class="section-title">Products</h1><p class="mt-2 text-sm text-slate-500">Manage inventory, product categories, publishing and Google Merchant status.</p></div><div class="flex gap-2"><Link href="/admin/catalog" class="btn-light">Manage categories</Link><Link href="/admin/products/create" class="btn-primary"><Icon name="add-circle" :size="17" /> Add product</Link></div></div>
        <div class="mt-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div class="metric-card"><div class="absolute right-0 top-0 h-20 w-20 rounded-bl-full bg-prinx-50"></div><p class="relative text-[10px] font-black uppercase tracking-[.15em] text-slate-400">Total products</p><b class="relative mt-2 block text-3xl font-black">{{ counts.active }}</b><p class="relative mt-1 text-xs text-slate-500">Available in management</p></div><div class="metric-card"><p class="text-[10px] font-black uppercase tracking-[.15em] text-emerald-600">Published</p><b class="mt-2 block text-3xl font-black">{{ counts.published }}</b><p class="mt-1 text-xs text-slate-500">Visible on the public store</p></div><div class="metric-card"><p class="text-[10px] font-black uppercase tracking-[.15em] text-amber-600">Drafts</p><b class="mt-2 block text-3xl font-black">{{ counts.drafts }}</b><p class="mt-1 text-xs text-slate-500">Waiting to be published</p></div><button class="metric-card text-left transition hover:border-red-200" @click="switchView('trash')"><p class="text-[10px] font-black uppercase tracking-[.15em] text-red-500">Trash</p><b class="mt-2 block text-3xl font-black">{{ counts.trash }}</b><p class="mt-1 text-xs text-slate-500">Restorable</p></button></div>
        <div class="mt-6 flex flex-wrap gap-2 rounded-[10px] border border-slate-200 bg-white p-2"><button :class="['tab-button', !trash ? 'bg-slate-950 text-white' : 'text-slate-600 hover:bg-slate-100']" @click="switchView('')">Current products <span class="rounded-[10px] bg-white/15 px-2 py-0.5 text-[10px]">{{ counts.active }}</span></button><button :class="['tab-button', trash ? 'bg-red-600 text-white' : 'text-slate-600 hover:bg-red-50 hover:text-red-600']" @click="switchView('trash')">Trash <span class="rounded-[10px] bg-white/15 px-2 py-0.5 text-[10px]">{{ counts.trash }}</span></button></div>
        <form class="card mt-5 grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-5" @submit.prevent="apply"><div class="relative xl:col-span-2"><Icon name="search-normal" :size="17" class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" /><input v-model="form.search" class="input pl-9" placeholder="Search product name or SKU"></div><select v-model="form.category" class="input"><option value="">All categories</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select><select v-if="!trash" v-model="form.status" class="input"><option value="">All statuses</option><option value="active">Active</option><option value="draft">Draft</option><option value="archived">Archived</option></select><select v-if="!trash" v-model="form.sync" class="input"><option value="">All sync states</option><option value="never">Never synced</option><option value="pending">Pending</option><option value="synced">Synced</option><option value="failed">Failed</option></select><input type="hidden" v-model="form.view"><button class="btn-primary md:col-span-2 xl:col-span-5 xl:justify-self-end">Apply filters</button></form>
        <div class="card mt-6 overflow-x-auto"><div class="flex items-center justify-between border-b border-slate-200 px-5 py-4"><div><h2 class="font-black">{{ trash ? 'Deleted products' : 'Product inventory' }}</h2><p class="mt-1 text-xs text-slate-500">{{ trash ? 'Nothing here is permanently deleted.' : `${products.total} products match the current filters.` }}</p></div><span v-if="trash" class="status bg-red-50 text-red-600">Soft delete only</span></div><table class="admin-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th v-if="!trash">Stock</th><th v-if="!trash">Store</th><th v-if="!trash">Merchant</th><th v-else>Deleted</th><th class="text-right">Actions</th></tr></thead><tbody><tr v-for="product in products.data" :key="product.id"><td><div class="flex min-w-64 items-center gap-3"><img :src="product.image_url" class="h-14 w-14 rounded-[10px] border border-slate-200 bg-slate-50 object-cover"><div><Link v-if="!trash" :href="`/admin/products/${product.slug}/edit`" class="font-black text-slate-900 hover:text-prinx-600">{{ product.name }}</Link><b v-else class="text-slate-900">{{ product.name }}</b><p class="mt-1 text-xs font-semibold text-slate-500">{{ product.sku }} · {{ product.brand?.name || 'No brand' }}</p></div></div></td><td><span class="rounded-[10px] bg-prinx-50 px-2.5 py-1 text-xs font-bold text-prinx-700">{{ product.category?.name || 'Uncategorised' }}</span></td><td class="font-black text-slate-950">{{ money(product.current_price) }}</td><td v-if="!trash"><span :class="product.in_stock ? 'font-bold text-emerald-600' : 'font-bold text-red-600'">{{ product.track_stock ? product.stock_quantity : 'Unlimited' }}</span></td><td v-if="!trash"><span :class="['status', statusBadge(product.status)]">{{ product.status }}</span></td><td v-if="!trash"><span :class="['status', syncBadge(product.merchant_sync_status)]">{{ product.merchant_sync_status }}</span><p v-if="product.merchant_sync_error" class="mt-1 max-w-44 truncate text-xs text-red-500" :title="product.merchant_sync_error">{{ product.merchant_sync_error }}</p></td><td v-else><span class="text-xs font-semibold text-slate-500">{{ new Date(product.deleted_at).toLocaleString() }}</span></td><td><div class="flex min-w-max justify-end gap-2"><template v-if="!trash"><button class="btn-light px-3 py-2" title="Sync to Google Merchant" @click="sync(product)">Sync</button><Link :href="`/admin/products/${product.slug}/edit`" class="btn-light px-3 py-2">Edit</Link><button class="btn-danger" @click="destroy(product)">Delete</button></template><button v-else class="btn-primary px-4" @click="restore(product)">Restore product</button></div></td></tr><tr v-if="!products.data.length"><td :colspan="trash ? 5 : 7" class="py-20 text-center"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-[10px] bg-slate-100 text-slate-500"><Icon name="box" :size="25" /></div><p class="mt-4 font-black text-slate-700">{{ trash ? 'Trash is empty' : 'No products found' }}</p><p class="mt-1 text-xs text-slate-400">{{ trash ? 'Deleted products will appear here.' : 'Change the filters or add a new product.' }}</p></td></tr></tbody></table></div><Pagination :links="products.links" />
    </AdminLayout>
</template>
